#[test]
fn v2_long_sliding_window_matches_reference() {
    let config_json = read_json("tiny_v2_config.json");
    let config = S3Config::from_json_with_defaults(&config_json, S3Config::v2()).unwrap();
    let file = SafetensorsFile::open(&testdata("tiny_v2_weights.safetensors")).unwrap();
    let tok = S3TokenizerV2::load(config, &file).unwrap();
    let traces = read_json("traces.json");

    let (_, mel_long) = read_npy("v2_long_mel.npy");
    let mel_len = traces["v2_long_mel_len"].as_u64().unwrap() as usize;
    let (codes, out_len) = tok.quantize(&mel_long, mel_len).unwrap();
    assert_eq!(
        out_len,
        traces["v2_long_code_len"].as_u64().unwrap() as usize
    );
    let (_, ref_codes) = read_npy_i32("v2_long_code.npy");
    for (i, (&a, &b)) in codes.iter().zip(ref_codes.iter()).enumerate() {
        if a != b {
            panic!(
                "Mismatch at index {i}: got {a}, expected {b}, len={}",
                codes.len()
            );
        }
    }
    assert_eq!(codes, ref_codes);
}

#[test]
fn log_mel_spectrogram_matches_reference() {
    let (_, wave) = read_npy("mel_wave.npy");
    let frames = log_mel_spectrogram(&wave, 128).unwrap();
    let traces = read_json("traces.json");
    let expected_shape: Vec<usize> = traces["mel_shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_u64().unwrap() as usize)
        .collect();
    // frames is [T, n_mels], reference is [n_mels, T]
    assert_eq!(frames.len(), expected_shape[1]);
    assert_eq!(frames[0].len(), expected_shape[0]);

    let (_, ref_spec) = read_npy("mel_golden.npy");
    let n_mels = expected_shape[0];
    let n_frames = expected_shape[1];
    let mut flat = vec![0.0f32; n_mels * n_frames];
    for t in 0..n_frames {
        for m in 0..n_mels {
            flat[m * n_frames + t] = frames[t][m];
        }
    }
    let diff = max_diff(&flat, &ref_spec);
    assert!(diff < 1e-4, "log-mel spectrogram difference {diff}");
}

#[test]
#[ignore = "requires real S3 checkpoint in TURBOSPARK_S3_MODEL_DIR"]
fn real_checkpoint_gate() {
    let dir = match std::env::var("TURBOSPARK_S3_MODEL_DIR") {
        Ok(dir) => PathBuf::from(dir),
        Err(_) => return,
    };
    let tok = S3TokenizerV2::open(&dir).expect("opens real checkpoint");
    assert_eq!(tok.config.n_codebook_size, 6561);
}
